public final class TFMGetGroupsVisitor implements TFMIDocumentHandlerVisitor
{
    Array               attributeArray;
    TFMPage             mobPage;
    TFMPages            mobPages;
    MapEnumerator		pagesEnum;
    TFMMenuAttribute    menuAttribute;
    int					i;
    Map					categories;

