Method.Source:
/// <summary>
/// Fetches the categories from the TFMMenu attribute
/// </summary>
void visitDocumentHandler(DictClass subClass, TFMDocumentHandler _documentHandler)
{
    attributeArray = subClass.getAttributes(classStr(TFMMenuAttribute));
    for (i = 1; i <= attributeArray.lastIndex(); i++)
    {
        menuAttribute = attributeArray.value(i);            
        categories.insert(menuAttribute.parmName(), menuAttribute.getCategories());            
    }
}
